"""Build three offline, auditable interaction labs from submitted CSV tables."""
from pathlib import Path
import csv, json, html
from task2_localization import NOC_ZH, SPORT_ZH

ROOT=Path(__file__).resolve().parents[2]
DEL=ROOT/'交付文件'
T3=DEL/'任务三_专题深挖'
T4=DEL/'任务四_开放创作'

def read(path):
    with path.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))

def dump(x):return json.dumps(x,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')

CSS='''<style>
:root{--bg:#f3f0e9;--paper:#fffefa;--ink:#122d36;--teal:#116f80;--red:#aa3d59;--gold:#bd8537;--line:#d8e0dc;--muted:#52666b}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:"Microsoft YaHei","Noto Sans SC",system-ui,sans-serif;line-height:1.7}a{color:var(--teal)}button,input,select{font:inherit}button,select,input[type=file]{border:1px solid var(--line);border-radius:10px;padding:9px 13px;background:var(--paper);color:var(--ink)}button{cursor:pointer}button:hover{transform:translateY(-2px);box-shadow:0 10px 25px #1237}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #eab46a;outline-offset:2px}nav{height:62px;display:flex;align-items:center;justify-content:space-between;padding:0 max(4vw,20px);background:#12343e;color:white;gap:12px}nav a{color:white;text-decoration:none}nav a:hover{text-decoration:underline}.wrap{max-width:1240px;margin:auto;padding:0 28px}header{padding:90px 0 55px;background:radial-gradient(circle at 80% 30%,#cde2dd,transparent 35%),linear-gradient(120deg,#f8f5ef,#e8efeb)}.eyebrow{font-size:13px;color:var(--red);font-weight:900;letter-spacing:.15em}h1{font-size:clamp(42px,6vw,76px);line-height:1.15;margin:12px 0 18px;letter-spacing:-.04em}h2{font-size:clamp(25px,3vw,40px);margin:0 0 12px}h3{margin:0 0 8px}.lead{font-size:clamp(17px,1.8vw,22px);max-width:840px;color:#37555a}.bar{height:12px;background:#dbe8e6;border-radius:12px;overflow:hidden}.bar i{display:block;height:100%;background:var(--teal);border-radius:12px;transition:width .4s}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.card{background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:24px;box-shadow:0 17px 44px -35px #163642}.card strong.metric{font-size:40px;line-height:1.2;color:var(--teal);display:block}.muted{color:var(--muted)}section{padding:56px 0;border-bottom:1px solid var(--line)}.controls{display:flex;align-items:end;gap:16px;flex-wrap:wrap;margin:20px 0}.controls label{display:grid;gap:5px;font-weight:700}.controls select{min-width:190px}.controls input[type=range]{width:min(430px,70vw);accent-color:var(--red)}table{border-collapse:collapse;width:100%;background:var(--paper)}th,td{padding:12px;border-bottom:1px solid var(--line);text-align:left}th{color:#436169;background:#e7efeb}.scroll{overflow:auto;border-radius:16px;border:1px solid var(--line)}tbody tr{transition:background .2s}tbody tr:hover{background:#eaf3ef}.pill{display:inline-block;border-radius:999px;background:#e4f0ed;padding:3px 10px;color:var(--teal);font-weight:800}.note{border-left:4px solid var(--gold);padding:14px 20px;background:#f8f0e3;border-radius:0 12px 12px 0}.chart{background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:15px;overflow:auto}svg{width:100%;height:auto}.cards2{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}footer{padding:50px 0;color:var(--muted)}@media(max-width:700px){.grid,.cards2{grid-template-columns:1fr}.wrap{padding:0 18px}nav{font-size:13px}th,td{padding:8px;font-size:12px}section{padding:36px 0}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition:none!important}}
</style>'''

def shell(title,eyebrow,lead,home,body,script,brand):
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title>{CSS}</head><body><header><div class="wrap"><div class="lab-breadcrumb"><a href="{brand}">作品总入口</a><span>／</span><a href="{home}">返回任务</a></div><div class="eyebrow">{eyebrow}</div><h1>{title}</h1><p class="lead">{lead}</p></div></header><main class="wrap">{body}</main><footer class="wrap">原始数据、计算表与口径说明随任务目录提供。页面离线运行，交互不会发送数据到服务器。</footer><script>{script}</script></body></html>'''

# 1. Continuous, explicitly hypothetical lens stress test.
rank=read(T3/'S2_口径的魔力/02_数据表/S2_2024三口径完整排名.csv')
by={}
for r in rank:
    if r['lens'] in ('official','rows'):
        by.setdefault(r['NOC'],{})[r['lens']]=float(r['Gold'])
lens=[{'code':k,'name':NOC_ZH.get(k,k),'official':v.get('official',0),'rows':v.get('rows',0)} for k,v in by.items() if 'official' in v and 'rows' in v]
lens.sort(key=lambda x:x['code'])
assert len(lens)>=50
cube=read(DEL/'任务一_数据体检/99_运行生成/analysis_cube.csv')
sport={}
for r in cube:
    if r['Year']=='2024' and r['Medal']=='Gold':
        key=(r['NOC'],r['sport_family']);sport[key]=sport.get(key,0)+int(r['records'])
sport_by={}
for (noc,sp),count in sport.items():sport_by.setdefault(noc,[]).append({'sport':SPORT_ZH.get(sp,sp),'rows':count})
for rows in sport_by.values():rows.sort(key=lambda x:-x['rows'])
lens_body='''<section><h2>拖动规则，看榜单何时翻转</h2><p class="muted">α = 0 是官方小项金牌；α = 1 是运动员金牌行。中间数值只是把两套计数线性混合的假设性压力测试，不是官方排名或公平性结论。</p><div class="controls"><label>口径权重 α <input id="alpha" type="range" min="0" max="100" value="0"></label><strong id="weight" class="pill">0%</strong><label>追踪代表团 <select id="noc"></select></label></div><div class="grid"><article class="card"><span>当前名次</span><strong class="metric" id="rankNow">—</strong><small id="rankPath"></small></article><article class="card"><span>下一次换位</span><strong class="metric" id="nextFlip">—</strong><small id="flipWith"></small></article><article class="card"><span>口径放大倍数</span><strong class="metric" id="multiplier">—</strong><small>运动员金牌行 ÷ 官方小项金牌</small></article></div></section><section><h2>动态前二十</h2><div class="scroll"><table><thead><tr><th>名次</th><th>代表团</th><th>假设性金牌分</th><th>官方小项</th><th>运动员行</th></tr></thead><tbody id="board"></tbody></table></div></section><section><h2>获奖行集中在哪些运动？</h2><p class="muted">下图按原始运动员金牌记录汇总，帮助解释行数膨胀的结构；不同运动的官方小项数不在此图中相减。</p><div id="sports" class="cards2"></div><p class="note">排名采用金牌分降序，同分并列最小名次。中间 α 值不是一套真实颁奖规则；换位阈值仅衡量结论对统计单位的敏感性。</p></section>'''
lens_js='''const DATA=__DATA__, SPORTS=__SPORTS__;const $=s=>document.querySelector(s),sel=$('#noc'),range=$('#alpha');for(const x of DATA){const o=document.createElement('option');o.value=x.code;o.textContent=x.name+' · '+x.code;sel.append(o)}sel.value='NED';const fmt=x=>Number(x).toFixed(1).replace(/\\.0$/,'');function list(a){const s=DATA.map(x=>({...x,score:x.official+a*(x.rows-x.official)})).sort((x,y)=>y.score-x.score||x.code.localeCompare(y.code));let rank=0,prev=null;for(let i=0;i<s.length;i++){if(prev===null||Math.abs(s[i].score-prev)>1e-8)rank=i+1;s[i].rank=rank;prev=s[i].score}return s}function render(){const a=+range.value/100,code=sel.value,all=list(a),x=DATA.find(d=>d.code===code),cur=all.find(d=>d.code===code);$('#weight').textContent=Math.round(a*100)+'%';$('#rankNow').textContent='第'+cur.rank+'位';const r0=list(0).find(d=>d.code===code).rank,r1=list(1).find(d=>d.code===code).rank;$('#rankPath').textContent='官方第'+r0+'位 → 行口径第'+r1+'位';$('#multiplier').textContent=x.official?fmt(x.rows/x.official)+'×':'无小项金牌';const flips=[];for(const y of DATA){if(y.code===code)continue;const dx=x.rows-x.official,dy=y.rows-y.official,den=dx-dy;if(Math.abs(den)<1e-10)continue;const t=(y.official-x.official)/den;if(t>a+0.0001&&t<=1.0001)flips.push({t,y})}flips.sort((u,v)=>u.t-v.t);$('#nextFlip').textContent=flips.length?Math.round(flips[0].t*100)+'%':'无';$('#flipWith').textContent=flips.length?'与'+flips[0].y.name+'的分值相交':'此区间内分值不再相交';const tbody=$('#board');tbody.replaceChildren();for(const y of all.slice(0,20)){const tr=document.createElement('tr');for(const value of [y.rank,y.name,fmt(y.score),fmt(y.official),fmt(y.rows)]){const td=document.createElement('td');td.textContent=value;tr.append(td)}if(y.code===code)tr.style.background='#fff1de';tbody.append(tr)}const box=$('#sports');box.replaceChildren();const rows=(SPORTS[code]||[]).slice(0,8),max=rows[0]?.rows||1;for(const z of rows){const d=document.createElement('div');d.className='card';const label=document.createElement('strong');label.textContent=z.sport+' · '+z.rows+'行';const bar=document.createElement('div');bar.className='bar';const i=document.createElement('i');i.style.width=(z.rows/max*100)+'%';bar.append(i);d.append(label,bar);box.append(d)}}range.oninput=render;sel.onchange=render;render();'''.replace('__DATA__',dump(lens)).replace('__SPORTS__',dump(sport_by))
path=T3/'S2_口径的魔力/07_口径实验室/index.html';path.parent.mkdir(parents=True,exist_ok=True)
path.write_text(shell('奖牌榜口径实验室','任务三 · 统计单位压力测试','同一届、同一金牌排序规则，改变统计单位会在什么位置改写名次？', '../../统一中文入口/index.html',lens_body,lens_js,'../../../作品总入口/index.html'),encoding='utf-8')

# 2. Observed survival of delegation control streaks; 2016 endings are right-censored.
dyn=read(T3/'S3_冠军的保质期/02_数据表/S3_冠军王朝清单.csv')
dyn_data=[]
for r in dyn:
    try:n=int(r['editions']);start=int(r['start_year']);end=int(r['end_year'])
    except ValueError:continue
    dyn_data.append({'sport':SPORT_ZH.get(r['Sport'],r['Sport_zh'] or r['Sport']),'event':r['Event_zh'] or r['Event'],'name':NOC_ZH.get(r['NOC'],r['NOC']),'start':start,'end':end,'length':n,'censored':end==2016})
assert len(dyn_data)>3000
surv_body='''<section><h2>一条王朝能守住几届？</h2><p class="muted">以同一代表团在同一小项连续夺金的届次数为寿命。2016年仍在延续的王朝按右删失处理；曲线是观察性生存估计，不是未来卫冕概率。</p><div class="controls"><label>运动 <select id="sport"><option value="">全部运动</option></select></label><label>起始年代 <select id="era"><option value="">全部年代</option><option value="1896-1948">1896—1948</option><option value="1952-1988">1952—1988</option><option value="1992-2016">1992—2016</option></select></label></div><div class="grid"><article class="card"><span>纳入王朝段</span><strong class="metric" id="streaks">—</strong></article><article class="card"><span>至少守住3届</span><strong class="metric" id="three">—</strong></article><article class="card"><span>最长连续控制</span><strong class="metric" id="longest">—</strong></article></div></section><section><h2>观察性生存曲线</h2><div class="chart"><svg id="curve" viewBox="0 0 900 380" role="img" aria-label="王朝连续夺冠届数生存曲线"></svg></div><p class="note">阶梯每下降一次，代表有王朝在该届数后终结。2016届右删失不记作失败。起始年代筛选按王朝首次夺冠年份；小项退出、改名及政体变化也可能截断记录；不同年代不可直接作因果比较。</p></section><section><h2>筛选后最长的王朝</h2><div class="scroll"><table><thead><tr><th>运动</th><th>小项</th><th>代表团</th><th>起止年份</th><th>连续届数</th></tr></thead><tbody id="top"></tbody></table></div></section>'''
surv_js='''const DATA=__DATA__,$=s=>document.querySelector(s);const sport=$('#sport'),era=$('#era');const names=[...new Set(DATA.map(x=>x.sport))].sort((a,b)=>a.localeCompare(b,'zh'));for(const n of names){const o=document.createElement('option');o.value=n;o.textContent=n;sport.append(o)}function render(){const e=era.value.split('-').map(Number),rows=DATA.filter(x=>(!sport.value||x.sport===sport.value)&&(!era.value||x.start>=e[0]&&x.start<=e[1]));$('#streaks').textContent=rows.length.toLocaleString();$('#three').textContent=(rows.length?rows.filter(x=>x.length>=3).length/rows.length*100:0).toFixed(1)+'%';$('#longest').textContent=(Math.max(0,...rows.map(x=>x.length)))+'届';const max=Math.min(12,Math.max(2,...rows.map(x=>x.length))),points=[[1,1]];let s=1;for(let k=1;k<=max;k++){const risk=rows.filter(x=>x.length>=k).length,death=rows.filter(x=>x.length===k&&!x.censored).length;if(risk)s*=1-death/risk;points.push([k+1,s])}const svg=$('#curve');svg.replaceChildren();const NS='http://www.w3.org/2000/svg',add=(type,attr,text)=>{const z=document.createElementNS(NS,type);for(const [k,v] of Object.entries(attr))z.setAttribute(k,v);if(text)z.textContent=text;svg.append(z)};for(let q=0;q<=4;q++){const yy=35+q*75;add('line',{x1:65,y1:yy,x2:860,y2:yy,stroke:'#d5e1df'});add('text',{x:14,y:yy+5,fill:'#52666b','font-size':15},(100-q*25)+'%')}const X=k=>65+(k-1)/max*795,Y=v=>35+(1-v)*300;let path='M'+X(1)+','+Y(1);for(const [k,v] of points)path+=' H'+X(k)+' V'+Y(v);add('path',{d:path,fill:'none',stroke:'#116f80','stroke-width':4,'stroke-linejoin':'round'});for(let k=1;k<=max+1;k+=Math.max(1,Math.ceil(max/8)))add('text',{x:X(k)-4,y:363,fill:'#52666b','font-size':15},String(k));add('text',{x:720,y:24,fill:'#52666b','font-size':15},'连续控制届数');const tbody=$('#top');tbody.replaceChildren();for(const x of rows.sort((a,b)=>b.length-a.length).slice(0,12)){const tr=document.createElement('tr');for(const v of [x.sport,x.event,x.name,x.start+'—'+x.end,x.length+(x.censored?' *':'')]){const td=document.createElement('td');td.textContent=v;tr.append(td)}tbody.append(tr)}}sport.onchange=render;era.onchange=render;render();'''.replace('__DATA__',dump(dyn_data))
path=T3/'S3_冠军的保质期/07_王朝生存图/index.html';path.parent.mkdir(parents=True,exist_ok=True)
path.write_text(shell('冠军王朝生存图','任务三 · 优势寿命','筛选运动与年代，观察连续夺冠的优势如何延续、终结和被数据边界截断。','../../统一中文入口/index.html',surv_body,surv_js,'../../../作品总入口/index.html'),encoding='utf-8')

# 3. Frozen forecast scorecard with local CSV import and an explicitly historic demo.
forecast=read(T4/'02_2028洛杉矶预测/LA2028机器学习集成预测榜.csv')
forecast_data=[{'code':r['NOC'],'name':NOC_ZH.get(r['NOC'],r['NOC']),'pred':float(r['ensemble_total']),'low':float(r['lower80']),'high':float(r['upper80'])} for r in forecast]
back=read(T4/'02_2028洛杉矶预测/历史回测逐队结果.csv')
demo=[{'code':r['NOC'],'name':NOC_ZH.get(r['NOC'],r['NOC']),'pred':float(r['pred_total']),'actual':float(r['actual_total'])} for r in back if r['Year']=='2024']
assert len(forecast_data)>=100 and len(demo)>=50
score_body='''<section><h2>先公开判分规则，再等待真实结果</h2><p>预测值固定为交付时的最终项目级集成模型。上传2028实际奖牌CSV（列名：<code>NOC,Gold,Silver,Bronze</code>），页面在本地计算总奖牌MAE、排名相关、前十命中和基线区间覆盖率。尚无2028实际结果时，不显示伪造的成绩。</p><div class="controls"><label>2028实际结果 <input id="file" type="file" accept=".csv,text/csv"></label><button id="template">下载空白模板</button><button id="demo">用2024历史回测演示</button><button id="reset">清空结果</button></div><p id="status" class="note">等待2028真实结果。可先用历史回测演示计算方式；演示结果不是2028模型成绩。</p><div class="grid"><article class="card"><span>总奖牌平均绝对误差</span><strong class="metric" id="mae">—</strong></article><article class="card"><span>名次等级相关</span><strong class="metric" id="rho">—</strong></article><article class="card"><span>前十重合</span><strong class="metric" id="top10">—</strong></article></div></section><section><h2>逐代表团误差表</h2><p id="coverage" class="muted">80%区间覆盖率将在2028实际结果上传后计算；该区间来自历史基线残差，并非集成模型的独立校准结果。</p><div class="scroll"><table><thead><tr><th>代表团</th><th>预测总牌</th><th>实际总牌</th><th>绝对误差</th><th>80%区间</th></tr></thead><tbody id="rows"></tbody></table></div></section><section><h2>怎样解释失准？</h2><div class="cards2"><article class="card"><h3>主场假设</h3><p>先检查美国及其他主办相关情景的误差；主办权不是随机分配，不能从预测偏差直接推出因果效应。</p></article><article class="card"><h3>新增项目假设</h3><p>再按板球、棒垒球、壁球等新增运动拆解；当前输入是赛前排名快照，不是确定奖牌。</p></article></div><p class="note">评估规则在赛前固定：所有实际有结果的NOC都纳入MAE与相关；前十按总奖牌降序、同分按代码排序。缺失代表团不自动当作零，需在正式评估前检查名单覆盖。</p></section>'''
score_js='''const P=__FORECAST__,D=__DEMO__,$=s=>document.querySelector(s);let mode='';function csvRows(text){text=text.replace(/^\\uFEFF/,'');const lines=text.trim().split(/\\r?\\n/);return lines.map(line=>{const cells=[];let value='',quoted=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='\"'){if(quoted&&line[i+1]==='\"'){value+='\"';i++}else quoted=!quoted}else if(ch===','&&!quoted){cells.push(value);value=''}else value+=ch}cells.push(value);return cells})}function ranks(data,key){const a=[...data].sort((x,y)=>y[key]-x[key]||x.code.localeCompare(y.code));return new Map(a.map((x,i)=>[x.code,i+1]))}function rho(rows){const a=ranks(rows,'pred'),b=ranks(rows,'actual'),n=rows.length;if(n<3)return NaN;let s=0;for(const x of rows)s+=(a.get(x.code)-b.get(x.code))**2;return 1-6*s/(n*(n*n-1))}function render(rows,isDemo){const n=rows.length,mae=rows.reduce((s,x)=>s+Math.abs(x.actual-x.pred),0)/n,A=ranks(rows,'pred'),B=ranks(rows,'actual'),overlap=rows.filter(x=>A.get(x.code)<=10&&B.get(x.code)<=10).length;$('#mae').textContent=mae.toFixed(2)+'枚';$('#rho').textContent=rho(rows).toFixed(3);$('#top10').textContent=overlap+'/10';const covered=rows.filter(x=>x.low!==undefined&&x.actual>=x.low&&x.actual<=x.high).length;$('#coverage').textContent=isDemo?'历史演示不使用2028预测区间；只检验计算方式。':'80%区间覆盖：'+covered+'/'+n+' = '+(covered/n*100).toFixed(1)+'%。该区间来自历史基线残差，并非集成模型的独立校准区间。';const tbody=$('#rows');tbody.replaceChildren();for(const x of [...rows].sort((a,b)=>Math.abs(b.actual-b.pred)-Math.abs(a.actual-a.pred)).slice(0,40)){const tr=document.createElement('tr');for(const v of [x.name||x.code,x.pred.toFixed(1),x.actual.toFixed(0),Math.abs(x.actual-x.pred).toFixed(1),x.low===undefined?'历史演示':x.low.toFixed(1)+'—'+x.high.toFixed(1)]){const td=document.createElement('td');td.textContent=v;tr.append(td)}tbody.append(tr)}}$('#template').onclick=()=>{const csv='NOC,Gold,Silver,Bronze\\n'+P.map(x=>x.code+',,,').join('\\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='LA2028实际奖牌_待填写.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#demo').onclick=()=>{render(D,true);$('#status').textContent='当前为2024历史回测演示，预测来自早期透明基线；不是2028集成模型验证成绩。'};$('#reset').onclick=()=>{$('#file').value='';$('#status').textContent='等待2028真实结果。';for(const id of ['mae','rho','top10'])$('#'+id).textContent='—';$('#rows').replaceChildren();$('#coverage').textContent='80%区间覆盖率将在2028实际结果上传后计算。'};$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const cells=csvRows(await file.text()),head=cells.shift().map(x=>x.trim()),required=['NOC','Gold','Silver','Bronze'];if(required.some(x=>!head.includes(x)))throw Error('列名须为 NOC,Gold,Silver,Bronze');const actual=new Map;for(const row of cells){const o=Object.fromEntries(head.map((h,i)=>[h,(row[i]||'').trim()]));if(!o.NOC)continue;const vals=['Gold','Silver','Bronze'].map(k=>Number(o[k]));if(vals.some(v=>!Number.isFinite(v)||v<0))throw Error('奖牌数须为非负数字：'+o.NOC);actual.set(o.NOC.toUpperCase(),vals.reduce((a,b)=>a+b,0))}const rows=P.filter(x=>actual.has(x.code)).map(x=>({...x,actual:actual.get(x.code)}));if(rows.length<20)throw Error('匹配代表团少于20个，请检查NOC代码');render(rows,false);$('#status').textContent='已在本地读取 '+rows.length+' 个代表团；文件未上传服务器。请核对未匹配代码与实际参赛名单。'}catch(err){$('#status').textContent='读取失败：'+err.message}};'''.replace('__FORECAST__',dump(forecast_data)).replace('__DEMO__',dump(demo))
path=T4/'06_赛后验收单/index.html';path.parent.mkdir(parents=True,exist_ok=True)
path.write_text(shell('2028预测赛后验收单','任务四 · 预先注册的判分规则','把预测留在赛前，把真实结果留给赛后。评委现在可以用历史回测演示计算流程。','../index.html',score_body,score_js,'../../作品总入口/index.html'),encoding='utf-8')
print(json.dumps({'lens_nocs':len(lens),'dynasty_streaks':len(dyn_data),'forecast_nocs':len(forecast_data),'demo_rows':len(demo)},ensure_ascii=False))


